// SAFE - parameterized query: input is data, not SQL
app.post('/login', (req, res) => {
  const { email, password } = req.body;
  const sql = 'SELECT id, email FROM users WHERE email = ? AND password_hash = ?';
  db.query(sql, [email, hash(password)], (err, rows) => {
    if (err) return res.status(500).json({ error: 'Server error' }); // don't leak err
    if (!rows.length) return res.status(401).json({ error: 'Invalid credentials' });
    res.json(rows[0]);
  });
});

